            | Self::DoomfistRisingUppercutLeapSound
            | Self::DvaMicroMissilesExplosionSound
            | Self::DvaSelfDestructExplosionSound
            | Self::EchoStickyBombExplosionSound
            | Self::HanzoSonicArrowInitialPulseSound
            | Self::JunkratConcussionMineExplosionSound
            | Self::JunkratFragLauncherExplosionSound
            | Self::JunkratRipTireExplosionSound
            | Self::LucioSoundBarrierCastSound
            | Self::MoiraFadeDisappearSound
            | Self::MoiraFadeReappearSound
